def wait_time(self, now, cost=1):
    """Seconds until `cost` tokens will be available (0 if available now)."""
    self.refill(now)
    if self.tokens >= cost:
        return 0.0
    missing = cost - self.tokens
    # The fractional remainder already counts toward the next token.
    return max(0.0, (missing - self._remainder) / self.rate)

def stats(self):
    with self._lock:
        now = self.clock()
        for b in self._buckets.values():
            b.refill(now)
        return {cid: b.tokens for cid, b in self._buckets.items()}

